struct SumJob : IJob
{
    [ReadOnly] public NativeArray<float> input;
    public float sum;                 // lives in the job's copy

    public void Execute()
    {
        for (int i = 0; i < input.Length; i++)
            sum += input[i];
    }
}

var job = new SumJob { input = input };
job.Schedule().Complete();
Debug.Log(job.sum);                   // 0: the job summed into its own copy

