[BurstCompile]
struct SumJob : IJob
{
    [ReadOnly] public NativeArray<float> input;
    public NativeReference<float> result;   // one value in native memory

    public void Execute()
    {
        float s = 0f;
        for (int i = 0; i < input.Length; i++)
            s += input[i];
        result.Value = s;                    // lands in shared memory
    }
}

var result = new NativeReference<float>(Allocator.TempJob);
new SumJob { input = input, result = result }.Schedule().Complete();
float total = result.Value;                 // read after Complete()
result.Dispose();

[BurstCompile]
struct DamageJob : IJobParallelFor
{
    [ReadOnly]  public NativeArray<float> armor;  // read only: other jobs may read it too
    [WriteOnly] public NativeArray<float> dealt;  // written only: reading it throws
    public NativeArray<float> hp;                 // read and written: exclusive
    public float damage;

    public void Execute(int i)
    {
        float d = math.max(0f, damage - armor[i]);
        dealt[i] = d;
        hp[i] -= d;
    }
}

struct CountJob : IJob
{
    [___] public NativeArray<int> ids;
    public ___<int> count;

    public void Execute()
    {
        int n = 0;
        for (int i = 0; i < ids.Length; i++)
            if (ids[i] > 0) n++;
        count.___ = n;
    }
}

[BurstCompile]
struct HealJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float> regen;
    [ReadOnly] public NativeArray<float> hp;
    public float dt;

    public void Execute(int i)
    {
        float add = regen[i] * dt;
        hp[i] = math.min(100f, hp[i] + add);
    }
}

