cards.solution:
[BurstCompile]
struct SumJob : IJob
{
    [ReadOnly] public NativeArray<float> input;
    public NativeReference<float> result;

    public void Execute()
    {
        float s = 0f;
        for (int i = 0; i < input.Length; i++) s += input[i];
        result.Value = s;   // one write to shared native memory
    }
}

public static class Stats
{
    public static float Sum(NativeArray<float> input)
    {
        var result = new NativeReference<float>(Allocator.TempJob);
        new SumJob { input = input, result = result }.Schedule().Complete();
        float total = result.Value;   // read only after Complete()
        result.Dispose();             // TempJob: free it yourself
        return total;
    }
}
